def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def bands(n, separators):
        result = []
        start = 0
        for s in separators:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < n:
            result.append((start, n))
        return result

    rb = bands(h, sep_rows)
    cb = bands(w, sep_cols)

    # Use the most populated region as the repeating tile.
    candidates = []
    for ri, (r0, r1) in enumerate(rb):
        for ci, (c0, c1) in enumerate(cb):
            count = sum(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1))
            candidates.append((count, ri, ci))
    _, sri, sci = max(candidates)

    sr0, sr1 = rb[sri]
    sc0, sc1 = cb[sci]
    tile = [row[sc0:sc1] for row in grid[sr0:sr1]]

    out = [row[:] for row in grid]
    for r0, r1 in rb:
        for c0, c1 in cb:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = tile[(r - r0) % len(tile)][(c - c0) % len(tile[0])]
    return out
